import React, { useState } from "react";


import "./styles.css"
import { getStore, parseDateMMDDYYYY } from "../../../stores/Utils";
import { NavLink, useNavigate } from "react-router-dom";
import { CloseModal, OpenModal } from "../../../components/DialogHRM";
import { SvgIcon_Cmpt } from "../../../components";
import DeleteAlert from "../../Inventory/component/deleteAlert";
import { delete_Comprobante } from "../../Comprobantes/services/server_fetching";

const Svg = SvgIcon_Cmpt();


const ViewComprobante  = ({ data, item, accountForm }) => {
	

	let accountD = getStore("account_ids")?.[getStore(accountForm)?.account];
	let subaccountD = getStore("sub_account_ids")?.[getStore(accountForm)?.subAccount];


	const navigate = useNavigate();

	const close =  (element) => {
		CloseModal({id:data.modalID});
		
	}


	
	
	return (
		<div style={{
			maxHeight: "80vh",
			width: "660px",
			overflow: "auto",
			background: "var(--hrm_palette-general-background-b)",
			borderRadius: 13,
			padding: "10px 19px 30px"
		}}>
			<div className="_dsplFlx ">
				<p className="title_collect">
					{ "Movimientos de la Cuenta"}
				</p>
			</div>

			<div className=" acc_dtls" style={{marginTop: 10}}>
				<div className="_dsplFlx"  >
					<div className="code" style={{color: "#646cff"}}>
						{accountD?.code} 
					</div>
					<div className="name">
						{accountD?. name}
					</div>
				</div>
				<div className="flexSpace"/>
				{subaccountD ?
				<div className="_dsplFlx"  style={{margin: "10px 0 0 18px"}}>
					<div className="code" >
						{subaccountD?.subAccount} 
					</div>
					<div className="name">
						{subaccountD?. subAccountName}
					</div>
				</div>
				:null}
			</div>
			<div className="_dsplFlx ">
				<div className="flexSpace"/>
				<p className="title_collect">
					{ "En el documento"}
				</p>
				<p className="form_title" >
				{item?. document}
				</p>
			</div>
			
			<div className="_dsplFlx cmp_dtls">
				
				<div className="flexSpace"/>
				<div className="_dsplFlx"  >
					
				</div>
			</div>




			
			<div className="_dsplFlx hdr_bar purple">
				<div className="tr_bar tr_bar_5">
					
				</div>
				<div className="tr_bar tr_bar_25">
					Comprobante
				</div>
				<div className="tr_bar tr_bar_20">
					Fecha
				</div>
				<div className="tr_bar tr_bar_25">
					Debito
				</div>
				<div className="tr_bar tr_bar_25">
					Credito
				</div>
			</div>
			

			{item?.operations?.map((element, ind43) => {
				
				return (
					<ViewMovPayCollectItm
						key={ind43}
						element={element}
						close={close}
					/>
				)
				
			})}

		</div>
	);
};

export default ViewComprobante;




const ViewMovPayCollectItm  = ({ element, close}) => {

	const rmvOperatIds =  () => {
		
		delete_Comprobante([element], close);
	}

	const clearErrors =  () => {
		let modaldata = {};
		modaldata["zIndex"] = 450;
		modaldata["height"] = "40vh";
		// data['observeResize']=true;
		modaldata["props"] = { minHeight: "1vh", overlay: true, closeEvent: ()=>{}  };
		modaldata["content"] = <DeleteAlert
			label={"Peligro va a eliminar un registro contable!!!"} 
			labelColor={"var(--hrm_palette-selected-nav-text)"} 
			body={"El registro estan corrupto pero debe saber que no podra recuperarlo"} 
			btnConfirm={"OK"}
			confirm={rmvOperatIds}
		/>
		OpenModal(modaldata);
	}

	
	if(!element?.["comprobanteId"]){
		return (
			<div className="_dsplFlx hdr_bar" >
				<div className="tr_bar_90">
					<div className="name comprobante_id"  style={{color:"var(--hrm_palette-selected-nav-text)"}}>
						El registro contiene errores
					</div>
				</div>
				<div className="tr_bar_10">
					<div className="icon" onClick={()=>clearErrors()}>
						<Svg name={"outline_delete"} color={"var(--hrm_palette-selected-nav-text)"}/>
					</div>
				</div>
			</div>
		)
	}


	return(
		<div className="_dsplFlx hdr_bar" >
			<div className="tr_bar_5" style={{marginLeft:1}}>
				<LabelToolkit 
					toolkitLabel={element.description}
				>
					<Svg 
						name={"help"} 
						color={"#000"}
						size={18}
					/>

				</LabelToolkit>
				
			</div>
			<div className="tr_bar tr_bar_25 comprobante_id" onClick={close}>
				<NavLink to={{
					pathname: "accounting-ledger" ,
					search: `?cId=${element.comprobanteId}`
				}}>
					{element.comprobanteId}
				</NavLink>
			</div>
			<div className="tr_bar tr_bar_20">
				{element.date && parseDateMMDDYYYY(element.date)}
			</div>
			<div className="tr_bar tr_bar_25">
				{(element.debit*1)?.toFixed(2)}
			</div>
			<div className="tr_bar tr_bar_25">
				{(element.credit*1)?.toFixed(2)}
			</div>
		</div>
	)
}



const LabelToolkit  = ({ color, children, toolkitLabel}) => {
	
	const [open, setOpen] = useState(true);
	const [show, setShow] = useState(true);

	const openInfo = (v) => {
		if(!show){
			setOpen(true)
			setTimeout(() => {
				setShow(true)
			}, 50);
		}
		else{
			setShow(false)
			setTimeout(() => {
				setOpen(false)
			}, 50);
		}
	}
	
	const mouseLeave = (v) => {
		if(show){
			setShow(false)
			setTimeout(() => {
				setOpen(false)
			}, 50);
		}
	}

	const mouseIn = (v) => {
		if(!show){
			setOpen(true)
			setTimeout(() => {
				setShow(true)
			}, 50);
		}
	}

	let maxW = toolkitLabel?.length;

	return (
		<div className="lbl_dts _dsplFlx" style={{color:color}} >
			
			<div onMouseLeave={mouseLeave}>
			{toolkitLabel?
				<div className="icon_info" onClick={openInfo}>
					{/* <Svg name={open?"Xclose":"alert"} color={"#2f2f2f"} size={18}/>*/}
					{open?
					<div className={"boxOpenInfo"} style={{opacity:show?1:0, maxWidth:  maxW*9}}>
						<div className={"boxInfo"} >
							<span>
								{toolkitLabel}
							</span>
						</div>
					</div>
					:null}
				</div>
				:null}
				<div onMouseMove={mouseIn}>
					{children}
				</div>
			</div>
		</div>
	)
}